{
  "items": [
    {
      "name": "ContinuousAt.eventually_lt",
      "module_name": "Mathlib.Topology.Order.OrderClosed",
      "kind": "theorem",
      "type": "∀ {α : Type u} {β : Type v} [inst : TopologicalSpace α] [inst_1 : LinearOrder α] [OrderClosedTopology α] {f g : β → α}\n  [inst_3 : TopologicalSpace β] {x₀ : β},\n  ContinuousAt f x₀ → ContinuousAt g x₀ → f x₀ < g x₀ → ∀ᶠ (x : β) in nhds x₀, f x < g x"
    },
    {
      "name": "StrictMonoOn.continuousAt_of_exists_between",
      "module_name": "Mathlib.Topology.Order.MonotoneContinuity",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {β : Type u_2} [inst : LinearOrder α] [inst_1 : TopologicalSpace α] [OrderTopology α]\n  [inst_3 : LinearOrder β] [inst_4 : TopologicalSpace β] [OrderTopology β] {f : α → β} {s : Set α} {a : α},\n  StrictMonoOn f s →\n    s ∈ nhds a →\n      (∀ b < f a, ∃ c ∈ s, f c ∈ Set.Ico b (f a)) → (∀ b > f a, ∃ c ∈ s, f c ∈ Set.Ioc (f a) b) → ContinuousAt f a"
    },
    {
      "name": "lt_subset_interior_le",
      "module_name": "Mathlib.Topology.Order.OrderClosed",
      "kind": "theorem",
      "type": "∀ {α : Type u} {β : Type v} [inst : TopologicalSpace α] [inst_1 : LinearOrder α] [OrderClosedTopology α] {f g : β → α}\n  [inst_3 : TopologicalSpace β], Continuous f → Continuous g → {b | f b < g b} ⊆ interior {b | f b ≤ g b}"
    },
    {
      "name": "continuousAt_of_monotoneOn_of_exists_between",
      "module_name": "Mathlib.Topology.Order.MonotoneContinuity",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {β : Type u_2} [inst : LinearOrder α] [inst_1 : TopologicalSpace α] [OrderTopology α]\n  [inst_3 : LinearOrder β] [inst_4 : TopologicalSpace β] [OrderTopology β] {f : α → β} {s : Set α} {a : α},\n  MonotoneOn f s →\n    s ∈ nhds a →\n      (∀ b < f a, ∃ c ∈ s, f c ∈ Set.Ioo b (f a)) → (∀ b > f a, ∃ c ∈ s, f c ∈ Set.Ioo (f a) b) → ContinuousAt f a"
    },
    {
      "name": "StrictMonoOn.continuousAt_of_image_mem_nhds",
      "module_name": "Mathlib.Topology.Order.MonotoneContinuity",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {β : Type u_2} [inst : LinearOrder α] [inst_1 : TopologicalSpace α] [OrderTopology α]\n  [inst_3 : LinearOrder β] [inst_4 : TopologicalSpace β] [OrderTopology β] [DenselyOrdered β] {f : α → β} {s : Set α}\n  {a : α}, StrictMonoOn f s → s ∈ nhds a → f '' s ∈ nhds (f a) → ContinuousAt f a"
    },
    {
      "name": "continuousWithinAt_inter_Ioi_iff_Ici",
      "module_name": "Mathlib.Topology.Order.LeftRight",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {β : Type u_2} [inst : TopologicalSpace α] [inst_1 : PartialOrder α] [inst_2 : TopologicalSpace β]\n  {a : α} {f : α → β} {s : Set α}, ContinuousWithinAt f (s ∩ Set.Ioi a) a ↔ ContinuousWithinAt f (s ∩ Set.Ici a) a"
    }
  ]
}

